package android.os;import java.util.ArrayDeque;public class Handler {private static final ArrayDeque<Runnable> queue=new ArrayDeque<Runnable>();public Handler(){}public Handler(Looper l){}public boolean post(Runnable r){queue.add(r);return true;}public boolean postDelayed(Runnable r,long d){queue.add(r);return true;}public void removeCallbacks(Runnable r){queue.remove(r);}public static int pending(){return queue.size();}public static void drain(){int n=0;while(!queue.isEmpty()){if(++n>1000)throw new AssertionError("Unbounded posted work");queue.remove().run();}}}
